package dynamoevents

import (
	"context"
	"errors"
	"testing"

	"github.com/aws/aws-sdk-go/aws"
	"github.com/aws/aws-sdk-go/aws/request"
	"github.com/aws/aws-sdk-go/service/dynamodb"
	"github.com/gravitational/teleport/lib/backend/memory"
	"github.com/stretchr/testify/require"
)

type testFieldsMapMigrationClient struct {
	scan  func(*dynamodb.ScanInput) (*dynamodb.ScanOutput, error)
	write func(*dynamodb.BatchWriteItemInput) (*dynamodb.BatchWriteItemOutput, error)
}

func (c testFieldsMapMigrationClient) ScanWithContext(_ aws.Context, input *dynamodb.ScanInput, _ ...request.Option) (*dynamodb.ScanOutput, error) {
	return c.scan(input)
}

func (c testFieldsMapMigrationClient) BatchWriteItemWithContext(_ aws.Context, input *dynamodb.BatchWriteItemInput, _ ...request.Option) (*dynamodb.BatchWriteItemOutput, error) {
	return c.write(input)
}

func migrationTestItem(session string, index string, fields string) map[string]*dynamodb.AttributeValue {
	return map[string]*dynamodb.AttributeValue{
		keySessionID:    {S: aws.String(session)},
		keyEventIndex:   {N: aws.String(index)},
		"EventType":     {S: aws.String("test.event")},
		"Fields":        {S: aws.String(fields)},
		"OtherMetadata": {BOOL: aws.Bool(true)},
	}
}

func TestFieldsMapMigrationRequestPreservesEvent(t *testing.T) {
	fields := `{"user":"alice","empty":"","nested":{"roles":[],"settings":{}},"large":9007199254740993,"nil":null}`
	item := migrationTestItem("session", "1", fields)
	request, err := fieldsMapMigrationRequest(item)
	require.NoError(t, err)

	converted := request.PutRequest.Item
	require.Nil(t, converted["Fields"])
	require.Equal(t, item["OtherMetadata"], converted["OtherMetadata"])
	require.NotNil(t, item["Fields"], "conversion must not mutate the scanned item")
	require.NotNil(t, converted["FieldsMap"].M)
	require.Equal(t, "9007199254740993", aws.StringValue(converted["FieldsMap"].M["large"].N))
	require.Equal(t, "", aws.StringValue(converted["FieldsMap"].M["empty"].S))
	require.NotNil(t, converted["FieldsMap"].M["nested"].M["roles"].L)
	require.NotNil(t, converted["FieldsMap"].M["nested"].M["settings"].M)
}

func TestFieldsMapMigrationResumesAfterFailedPage(t *testing.T) {
	ctx := context.Background()
	store, err := memory.New(memory.Config{})
	require.NoError(t, err)
	defer store.Close()
	l := &Log{Config: Config{Tablename: "audit"}, backend: store}
	first := migrationTestItem("first", "1", `{"user":"alice"}`)
	second := migrationTestItem("second", "2", `{"user":"bob"}`)
	cursor := map[string]*dynamodb.AttributeValue{
		keySessionID:  first[keySessionID],
		keyEventIndex: first[keyEventIndex],
	}
	var scanCalls, writeCalls int
	client := testFieldsMapMigrationClient{
		scan: func(input *dynamodb.ScanInput) (*dynamodb.ScanOutput, error) {
			scanCalls++
			require.True(t, aws.BoolValue(input.ConsistentRead))
			require.Equal(t, "attribute_exists(#fields)", aws.StringValue(input.FilterExpression))
			if scanCalls == 1 {
				require.Empty(t, input.ExclusiveStartKey)
				return &dynamodb.ScanOutput{Items: []map[string]*dynamodb.AttributeValue{first}, LastEvaluatedKey: cursor}, nil
			}
			require.Equal(t, cursor, input.ExclusiveStartKey)
			return &dynamodb.ScanOutput{Items: []map[string]*dynamodb.AttributeValue{second}}, nil
		},
		write: func(input *dynamodb.BatchWriteItemInput) (*dynamodb.BatchWriteItemOutput, error) {
			writeCalls++
			require.Len(t, input.RequestItems["audit"], 1)
			if writeCalls == 2 {
				return nil, errors.New("temporary write failure")
			}
			return &dynamodb.BatchWriteItemOutput{}, nil
		},
	}
	require.Error(t, l.migrateFieldsMapWithClient(ctx, client))
	require.Equal(t, 2, scanCalls)
	state, err := l.loadFieldsMapMigrationState(ctx)
	require.NoError(t, err)
	require.Equal(t, cursor, state.LastEvaluatedKey)
	require.EqualValues(t, 1, state.MigratedCount)
	require.True(t, state.CompletedAt.IsZero())

	resumedScans := 0
	client = testFieldsMapMigrationClient{
		scan: func(input *dynamodb.ScanInput) (*dynamodb.ScanOutput, error) {
			resumedScans++
			require.Equal(t, cursor, input.ExclusiveStartKey)
			return &dynamodb.ScanOutput{Items: []map[string]*dynamodb.AttributeValue{second}}, nil
		},
		write: func(input *dynamodb.BatchWriteItemInput) (*dynamodb.BatchWriteItemOutput, error) {
			require.Len(t, input.RequestItems["audit"], 1)
			return &dynamodb.BatchWriteItemOutput{}, nil
		},
	}
	require.NoError(t, l.migrateFieldsMapWithClient(ctx, client))
	require.Equal(t, 1, resumedScans)
	state, err = l.loadFieldsMapMigrationState(ctx)
	require.NoError(t, err)
	require.Empty(t, state.LastEvaluatedKey)
	require.EqualValues(t, 2, state.MigratedCount)
	require.False(t, state.CompletedAt.IsZero())
}

func TestFieldsMapMigrationRetriesInvalidRecords(t *testing.T) {
	ctx := context.Background()
	store, err := memory.New(memory.Config{})
	require.NoError(t, err)
	defer store.Close()
	l := &Log{Config: Config{Tablename: "audit"}, backend: store}
	valid := migrationTestItem("valid", "1", `{"user":"alice"}`)
	invalid := migrationTestItem("invalid", "2", `{"user":`)
	var written int
	client := testFieldsMapMigrationClient{
		scan: func(*dynamodb.ScanInput) (*dynamodb.ScanOutput, error) {
			return &dynamodb.ScanOutput{Items: []map[string]*dynamodb.AttributeValue{valid, invalid}}, nil
		},
		write: func(input *dynamodb.BatchWriteItemInput) (*dynamodb.BatchWriteItemOutput, error) {
			written += len(input.RequestItems["audit"])
			return &dynamodb.BatchWriteItemOutput{}, nil
		},
	}
	err = l.migrateFieldsMapWithClient(ctx, client)
	require.Error(t, err)
	require.Contains(t, err.Error(), "could not convert 1 audit events")
	require.Equal(t, 1, written)
	state, err := l.loadFieldsMapMigrationState(ctx)
	require.NoError(t, err)
	require.Empty(t, state.LastEvaluatedKey)
	require.True(t, state.CompletedAt.IsZero())

	// Once the bad record is repaired, the next pass starts from the first
	// page and can finish. Previously converted rows no longer match the scan.
	repaired := migrationTestItem("invalid", "2", `{"user":"bob"}`)
	client.scan = func(input *dynamodb.ScanInput) (*dynamodb.ScanOutput, error) {
		require.Empty(t, input.ExclusiveStartKey)
		return &dynamodb.ScanOutput{Items: []map[string]*dynamodb.AttributeValue{repaired}}, nil
	}
	require.NoError(t, l.migrateFieldsMapWithClient(ctx, client))
	require.Equal(t, 2, written)
}

func TestValidateFieldsMapContentUsesJSONNumberSemantics(t *testing.T) {
	require.NoError(t, validateFieldsMapContent([]byte(`{"number":1.0,"nested":[-0,2e1]}`), []byte(`{"nested":[0,20],"number":1}`)))
	require.Error(t, validateFieldsMapContent([]byte(`{"number":9007199254740993}`), []byte(`{"number":9007199254740992}`)))
	require.Error(t, validateFieldsMapContent([]byte(`{"number":"1"}`), []byte(`{"number":1}`)))
}

