type event struct {
	SessionID      string
	EventIndex     int64
	EventType      string
	CreatedAt      int64
	Expires        *int64                              `json:"Expires,omitempty"`
	Fields         string                              `json:"Fields,omitempty"`
	FieldsMap      map[string]*dynamodb.AttributeValue `json:"-" dynamodbav:"-"`
	LegacyEventKey string                              `json:"LegacyEventKey,omitempty"`
	EventNamespace string
	CreatedAtDate  string
}

const (
	// keyExpires is a key used for TTL specification
	keyExpires = "Expires"

	// keySessionID is event SessionID dynamodb key
	keySessionID = "SessionID"

	// keyEventIndex is EventIndex key
	keyEventIndex = "EventIndex"

	// keyCreatedAt identifies created at key
	return values, string(lastKey), nil
}

func getSubPageCheckpoint(e *event) (string, error) {
	// The DynamoDB primary key does not change when Fields is migrated to
	// FieldsMap, so a cursor remains valid across a background conversion.
	hash := sha256.Sum256([]byte(e.SessionID + ":" + strconv.FormatInt(e.EventIndex, 10)))
	return hex.EncodeToString(hash[:]), nil
}

// Legacy cursors hashed the entire event. Migration stores that hash before
// deleting Fields, so a query started before an upgrade can still resume.
func legacySubPageCheckpoint(e *event) string {
	if e.LegacyEventKey != "" {
		return e.LegacyEventKey
	}
	if e.Fields == "" {
		return ""
	}
	data, err := utils.FastMarshal(e)
	if err != nil {
		return ""
	}
	hash := sha256.Sum256(data)
	return hex.EncodeToString(hash[:])
}

// SearchSessionEvents returns session related events only. This is used to
