func getSubPageCheckpoint(e *event) (string, error) {
	// The DynamoDB primary key does not change when Fields is migrated to
	// FieldsMap, so a cursor remains valid across a background conversion.
	hash := sha256.Sum256([]byte(e.SessionID + ":" + strconv.FormatInt(e.EventIndex, 10)))
	return hex.EncodeToString(hash[:]), nil
}

// Legacy cursors hashed the entire event. Migration stores that hash before
// deleting Fields, so a query started before an upgrade can still resume.
func legacySubPageCheckpoint(e *event) string {
	if e.LegacyEventKey != "" {
		return e.LegacyEventKey
	}
	if e.Fields == "" {
		return ""
	}
	data, err := utils.FastMarshal(e)
	if err != nil {
		return ""
	}
	hash := sha256.Sum256(data)
	return hex.EncodeToString(hash[:])
}

